import json

# Refined pattern from demo:
# row 0: input[0][c%2] for all columns
# row 1: input[1][c%2] for c=0,1, input[0][0] for c=2, input[1][1] for c=3
# row 2: input[0][0] for c=0,1,2, input[1][1] for c=3
# row 3: input[1][c%2] for all columns

input_grid = [[0, 0, 0, 0],
              [2, 2, 2, 0],
              [9, 9, 2, 0],
              [7, 9, 2, 0]]

output = []
for r in range(4):
    row = []
    for c in range(4):
        if r == 0:
            row.append(input_grid[0][c % 2])
        elif r == 1:
            if c < 2:
                row.append(input_grid[1][c % 2])
            elif c == 2:
                row.append(input_grid[0][0])
            else:
                row.append(input_grid[1][1])
        elif r == 2:
            if c < 3:
                row.append(input_grid[0][0])
            else:
                row.append(input_grid[1][1])
        elif r == 3:
            row.append(input_grid[1][c % 2])
    output.append(row)

print("Demo verification:")
req = [[9, 8], [8, 8]]
exp = [[9, 8, 9, 8], [8, 8, 9, 8], [9, 9, 9, 8], [8, 8, 8, 8]]
out = []
for r in range(4):
    out_row = []
    for c in range(4):
        if r == 0:
            out_row.append(req[0][c % 2])
        elif r == 1:
            if c < 2:
                out_row.append(req[1][c % 2])
            elif c == 2:
                out_row.append(req[0][0])
            else:
                out_row.append(req[1][1])
        elif r == 2:
            if c < 3:
                out_row.append(req[0][0])
            else:
                out_row.append(req[1][1])
        elif r == 3:
            out_row.append(req[1][c % 2])
    out.append(out_row)
for i, (a, b) in enumerate(zip(out, exp)):
    print(f"row {i}: {a} vs {b}, match={a==b}")
print()
print("Submitting:")
print(json.dumps({"action": "submit", "grid": output}))

